<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { api } from '../api'
import { useListBackLocation } from '../composables/listNavigation'
import type { Company, Page, Product } from '../types'
import { companyTitle } from '../utils'
import { useRecordEditor } from '../composables/recordEditor'
import { useEvents } from '../events'
import CompanyLogo from '../components/CompanyLogo.vue'
import CompanySelect from '../components/CompanySelect.vue'
import ItemCard from '../components/ItemCard.vue'
import RevisionPanel from '../components/RevisionPanel.vue'
import ConflictDialog from '../components/ConflictDialog.vue'
import SettingLinks from '../components/SettingLinks.vue'
const backTo = useListBackLocation('/companies')
const route = useRoute(); const router = useRouter(); const id = route.params.id as string; const items = ref<Product[]>([]); const showHistory = ref(false); const merging = ref(false); const targetID = ref(''); const busy = ref(false)
const { record: company, loading, saving, error, remoteNotice, dirty, conflict, apply, load, save, useServer, mergeLatest } = useRecordEditor<Company>(`/companies/${id}`, c => ({ chinese_name: c.chinese_name, english_name: c.english_name, aliases: c.aliases, description: c.description }))
async function loadItems() { try { const p = new URLSearchParams({ company_id: id, limit: '100' }); const [goods,tools] = await Promise.all([api<Page<Product>>(`/products?${p}`),api<Page<Product>>(`/tools?${p}`)]); items.value = [...goods.items,...tools.items] } catch (e) { error.value = (e as Error).message } }
async function remove() { if (!company.value || !confirm('将这家公司移入回收站？有关联商品或道具时，请先更换所属公司或合并。')) return; try { await api(`/companies/${id}`,{ method: 'DELETE', body: JSON.stringify({ version: company.value.version }) }); apply(company.value as Company); await router.push(backTo.value) } catch (e) { error.value = (e as Error).message } }
async function merge() { if (!company.value || !targetID.value) return; if (dirty.value) { error.value = '请先保存当前公司修改，再合并公司'; return }; busy.value = true; error.value = ''; try { const target = await api<Company>(`/companies/${targetID.value}`); if (!confirm(`将“${companyTitle(company.value)}”的商品、道具与灵感关联转到“${companyTitle(target)}”？当前公司资料将保留在回收站。`)) return; await api(`/companies/${id}/merge`,{ method: 'POST', body: JSON.stringify({ version: company.value.version, target_id: target.id, target_version: target.version }) }); await router.push(`/companies/${target.id}`) } catch (e) { error.value = (e as Error).message } finally { busy.value = false } }
onMounted(loadItems); useEvents(loadItems)
</script>
<template><p v-if="loading" class="muted">读取中…</p><p v-else-if="!company" class="error-text">{{ error }}</p><template v-else><div class="page-heading"><div><RouterLink :to="backTo">← 返回公司库</RouterLink><h1>{{ companyTitle(company) }}</h1><p>{{ company.item_count }} 件关联商品与道具</p></div><div class="heading-actions"><button class="secondary" @click="showHistory = !showHistory">修改历史</button><button class="text-button danger-text" @click="remove">移入回收站</button></div></div><p v-if="remoteNotice" class="ai-status">公司资料已有新修改，保存时会展示差异。</p><div class="detail-layout"><div class="detail-main"><form class="panel record-form" @submit.prevent="save"><h2>公司资料</h2><div class="field-inline"><label>公司中文名<input v-model="company.chinese_name" maxlength="160" /></label><label>公司英文名<input v-model="company.english_name" maxlength="160" /></label></div><label>简称／别名<input v-model="company.aliases" maxlength="2000" /></label><label>公司简介／世界观设定<textarea v-model="company.description" rows="6" maxlength="100000"></textarea></label><p v-if="error" class="error-text" role="alert">{{ error }}</p><div class="form-actions"><button class="primary" :disabled="saving || !dirty">{{ saving ? '保存中…' : dirty ? '保存修改' : '已保存' }}</button><span v-if="dirty" class="muted">有未保存修改</span></div></form><section class="panel"><h2>公司 Logo</h2><CompanyLogo v-model="company.attachments" :company-id="id" /></section><RevisionPanel v-if="showHistory" kind="company" :id="id" :version="company.version" @restored="load(true)" /><section class="panel"><h2>关联商品与道具</h2><div class="product-grid"><ItemCard v-for="item in items" :key="item.id" :item="item" /></div><p v-if="!items.length" class="muted">还没有关联物品，在商品或道具中选择这家公司即可。</p><div class="inline-controls related-heading"><RouterLink :to="`/products?company_id=${id}`">查看旗下全部商品 →</RouterLink><RouterLink :to="`/tools?company_id=${id}`">查看旗下全部道具 →</RouterLink></div></section><details class="panel"><summary @click="merging = true">合并到其他公司</summary><div v-if="merging" class="supplement"><p class="muted">商品和道具转到目标公司，当前公司的名称、设定与 Logo 留在回收站中。</p><CompanySelect v-model="targetID" :exclude="id" /><button class="secondary related-heading" :disabled="!targetID || busy || dirty" @click="merge">合并公司</button></div></details></div><aside class="side-panel"><section class="panel"><h2>关联灵感</h2><SettingLinks kind="company" :id="id" /></section></aside></div><ConflictDialog v-if="conflict" :current="conflict.current" :submitted="conflict.submitted" @server="useServer" @merge="mergeLatest" @cancel="conflict = undefined" /></template></template>
